import requests

def model_api(messages, model):
    headers = {
        "Authorization": "Bearer YOUR_API_KEY_HERE",
        "Content-Type": "application/json",
    }

    payload = {
        "model": model,
        "messages": messages,
        "max_tokens": 750,
    }

    response = requests.post(
        "https://api.fanar.qa/v1/chat/completions", 
        json=payload, 
        headers=headers
    )
    return response.json()

