# Fanar-2.0-Tools requires additional authorization and is not allowed by default.
#
# The model never runs a tool. It answers with the calls to make (finish_reason
# "tool_calls"); your code runs them, sends each result back as a "tool" message,
# and the model answers from the results. To get the best from it:
#   - Keep the whole exchange in the history, on later turns too: the assistant
#     turn with its tool_calls, then one "tool" message per call, in call order.
#     The model reads its own calls to know which result answers what.
#   - Never leave a call without a result. Return results as text (JSON is fine),
#     failures included, e.g. {"error": "..."}.
#   - Bound the round trips. On the last one, send tool_choice="none" and the
#     model answers from the results it has.
#   - A system message is optional; if you send one, it must be the first message.
#   - The context is 8K tokens. Keep the tool list and the history short; a request
#     that does not fit is refused with HTTP 413.
#   - tool_choice is "auto" (the default) or "none"; "required" and a named
#     function are refused, and so is parallel_tool_calls=false.
#   - Want structured output? Define a tool for it rather than asking for a JSON
#     answer: a reply that starts with "{" is taken for a tool call and lost.
#   - Arguments are written by the model and are not screened. Check them before
#     acting on them -- above all before one that books, pays or sends.
#   - Every round trip is one request against your rate limit.

import json
from datetime import datetime
from zoneinfo import ZoneInfo

from openai import OpenAI

client = OpenAI(
    base_url="https://api.fanar.qa/v1",
    api_key="YOUR_API_KEY_HERE",
)

# A travel assistant. These functions are stand-ins; yours would call real services.
def get_weather(city, unit="celsius"):
    celsius = {"doha": 34, "cairo": 27}.get(city.lower(), 25)
    temperature = celsius if unit == "celsius" else round(celsius * 9 / 5 + 32)
    return {"city": city, "temperature": temperature, "unit": unit, "condition": "sunny"}

def get_local_time(timezone):
    now = datetime.now(ZoneInfo(timezone))
    return {"timezone": timezone, "local_time": now.strftime("%Y-%m-%d %H:%M")}

def convert_currency(amount, from_currency, to_currency):
    per_usd = {"USD": 1.0, "QAR": 3.64, "EGP": 48.5, "SAR": 3.75, "EUR": 0.92}
    value = amount / per_usd[from_currency] * per_usd[to_currency]
    return {"amount": amount, "from": from_currency, "to": to_currency, "converted": round(value, 2)}

def search_flights(origin, destination, date, passengers, cabin="economy"):
    return {"flights": [
        {"flight_id": "QR1301", "departs": f"{date} 08:10", "arrives": f"{date} 10:55", "total_price_qar": 4350},
        {"flight_id": "MS910", "departs": f"{date} 13:45", "arrives": f"{date} 16:20", "total_price_qar": 3540},
        {"flight_id": "QR1303", "departs": f"{date} 19:30", "arrives": f"{date} 22:15", "total_price_qar": 3990},
    ]}

def book_flight(flight_id):
    return {"flight_id": flight_id, "status": "confirmed", "booking_reference": "FNR7X2"}

functions = {f.__name__: f for f in (get_weather, get_local_time, convert_currency, search_flights, book_flight)}

def tool(name, description, properties, required):
    return {"type": "function", "function": {
        "name": name, "description": description,
        "parameters": {"type": "object", "properties": properties, "required": required},
    }}

tools = [
    tool("get_weather", "Get the current weather in a city.", {
        "city": {"type": "string", "description": "City name, e.g. Doha"},
        "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]},
    }, ["city"]),
    tool("get_local_time", "Get the current local time in a timezone.", {
        "timezone": {"type": "string", "description": "IANA timezone, e.g. Asia/Qatar"},
    }, ["timezone"]),
    tool("convert_currency", "Convert an amount of money between currencies.", {
        "amount": {"type": "number"},
        "from_currency": {"type": "string", "description": "ISO 4217 code, e.g. QAR"},
        "to_currency": {"type": "string", "description": "ISO 4217 code, e.g. EGP"},
    }, ["amount", "from_currency", "to_currency"]),
    tool("search_flights", "Search flights between two cities on a date.", {
        "origin": {"type": "string"},
        "destination": {"type": "string"},
        "date": {"type": "string", "description": "YYYY-MM-DD"},
        "passengers": {
            "type": "object",
            "properties": {"adults": {"type": "integer"}, "children": {"type": "integer"}},
            "required": ["adults"],
        },
        "cabin": {"type": "string", "enum": ["economy", "business"]},
    }, ["origin", "destination", "date", "passengers"]),
    tool("book_flight", "Book a flight found by search_flights.", {
        "flight_id": {"type": "string"},
    }, ["flight_id"]),
]

def run(call):
    function = functions.get(call.function.name)
    if function is None:
        return {"error": f"Unknown tool {call.function.name}"}
    try:
        return function(**json.loads(call.function.arguments))
    except Exception as e:  # tell the model, rather than stopping
        return {"error": str(e)}

# One conversation: every question, call, result and answer stays in it.
messages = []
MAX_ROUNDS = 5

def ask(question):
    messages.append({"role": "user", "content": question})
    for round_number in range(1, MAX_ROUNDS + 1):
        response = client.chat.completions.create(
            model="Fanar-2.0-Tools",
            messages=messages,
            tools=tools,
            temperature=0,
            # Out of rounds: no more calls, answer from what you have.
            tool_choice="none" if round_number == MAX_ROUNDS else "auto",
        )
        choice = response.choices[0]
        if choice.finish_reason != "tool_calls":
            messages.append({"role": "assistant", "content": choice.message.content})
            return choice.message.content

        # The model's turn, calls included, then one result per call, in order.
        # Several calls can come at once: run them all before asking again.
        messages.append({
            "role": "assistant",
            "content": choice.message.content,
            "tool_calls": [call.model_dump() for call in choice.message.tool_calls],
        })
        for call in choice.message.tool_calls:
            print(f"  -> {call.function.name}({call.function.arguments})")
            messages.append({
                "role": "tool",
                "tool_call_id": call.id,
                "content": json.dumps(run(call), ensure_ascii=False),
            })

# Three tools in one answer: weather, local time and currency.
print(ask("I'm flying from Doha to Cairo. What's the weather and the local time in Cairo, "
          "and how much is 1,000 Qatari riyals in Egyptian pounds?"))

# A nested argument: passengers is an object.
print(ask("Find us economy flights from Doha to Cairo on 2026-11-06, two adults and one child."))

# A call that depends on an earlier result: the flight id comes from the search above.
print(ask("Book the cheapest one."))

