# Fanar-2.0-Tools requires additional authorization and is not allowed by default.
# The loop of "Python - Tool calling (Fanar-2.0-Tools)", streamed: text is printed as it
# arrives; tool calls are collected by index and run once the stream ends with
# finish_reason "tool_calls". The same rules apply: keep every call and result in the
# history, one result per call in call order, tool_choice="none" on the last round.

import asyncio
import json
from datetime import datetime
from zoneinfo import ZoneInfo

from openai import AsyncOpenAI

client = AsyncOpenAI(
    base_url="https://api.fanar.qa/v1",
    api_key="YOUR_API_KEY_HERE",
)

# Stand-ins for your own services.
def get_weather(city):
    celsius = {"doha": 34, "cairo": 27}.get(city.lower(), 25)
    return {"city": city, "temperature": celsius, "unit": "celsius", "condition": "sunny"}

def get_local_time(timezone):
    now = datetime.now(ZoneInfo(timezone))
    return {"timezone": timezone, "local_time": now.strftime("%Y-%m-%d %H:%M")}

def convert_currency(amount, from_currency, to_currency):
    per_usd = {"USD": 1.0, "QAR": 3.64, "EGP": 48.5, "SAR": 3.75, "EUR": 0.92}
    value = amount / per_usd[from_currency] * per_usd[to_currency]
    return {"amount": amount, "from": from_currency, "to": to_currency, "converted": round(value, 2)}

functions = {f.__name__: f for f in (get_weather, get_local_time, convert_currency)}

def tool(name, description, properties, required):
    return {"type": "function", "function": {
        "name": name, "description": description,
        "parameters": {"type": "object", "properties": properties, "required": required},
    }}

tools = [
    tool("get_weather", "Get the current weather in a city.",
         {"city": {"type": "string", "description": "City name, e.g. Doha"}}, ["city"]),
    tool("get_local_time", "Get the current local time in a timezone.",
         {"timezone": {"type": "string", "description": "IANA timezone, e.g. Asia/Qatar"}}, ["timezone"]),
    tool("convert_currency", "Convert an amount of money between currencies.", {
        "amount": {"type": "number"},
        "from_currency": {"type": "string", "description": "ISO 4217 code, e.g. QAR"},
        "to_currency": {"type": "string", "description": "ISO 4217 code, e.g. EGP"},
    }, ["amount", "from_currency", "to_currency"]),
]

async def main():
    messages = [{"role": "user", "content": "What's the weather and the local time in Cairo, "
                                            "and how much is 1,000 Qatari riyals in Egyptian pounds?"}]

    max_rounds = 5
    for round_number in range(1, max_rounds + 1):
        stream = await client.chat.completions.create(
            model="Fanar-2.0-Tools",
            messages=messages,
            tools=tools,
            temperature=0,
            stream=True,
            # Out of rounds: no more calls, answer from what you have.
            tool_choice="none" if round_number == max_rounds else "auto",
        )
        content, calls, finish_reason = "", {}, None
        async for chunk in stream:
            if not chunk.choices:
                continue
            choice = chunk.choices[0]
            if choice.delta.content:
                content += choice.delta.content
                print(choice.delta.content, end="", flush=True)
            # A call may arrive whole or in pieces; gather it by its index.
            for call in choice.delta.tool_calls or []:
                slot = calls.setdefault(call.index, {"id": None, "name": "", "arguments": ""})
                slot["id"] = call.id or slot["id"]
                if call.function:
                    slot["name"] += call.function.name or ""
                    slot["arguments"] += call.function.arguments or ""
            finish_reason = choice.finish_reason or finish_reason

        if finish_reason != "tool_calls":
            print()
            break

        calls = [calls[index] for index in sorted(calls)]
        messages.append({
            "role": "assistant",
            "content": content or None,
            "tool_calls": [
                {"id": c["id"], "type": "function",
                 "function": {"name": c["name"], "arguments": c["arguments"]}}
                for c in calls
            ],
        })
        for c in calls:  # one result per call, in order
            print(f"  -> {c['name']}({c['arguments']})")
            try:
                result = functions[c["name"]](**json.loads(c["arguments"]))
            except Exception as e:  # tell the model, rather than stopping
                result = {"error": str(e)}
            messages.append({
                "role": "tool",
                "tool_call_id": c["id"],
                "content": json.dumps(result, ensure_ascii=False),
            })

asyncio.run(main())

