// Node 18+ (built-in fetch, FormData and Blob). Submit in the background, poll until it ends.
import { readFile } from "node:fs/promises";

const BASE_URL = "https://api.fanar.qa";
const headers = { Authorization: "Bearer YOUR_API_KEY" };

interface Job {
  id: string;
  status: "queued" | "in_progress" | "completed" | "failed" | "cancelled";
  result: { text?: string; srt?: string; json?: { segments: unknown[] } } | null;
  error: { code: string; message: string } | null;
}

async function main(): Promise<void> {
  const form = new FormData();
  form.append("file", new Blob([new Uint8Array(await readFile("meeting.mp3"))]), "meeting.mp3");
  form.append("model", "Fanar-3.0-Aura-Transcribe");
  form.append("background", "true");

  const created = await fetch(`${BASE_URL}/v1/audio/transcriptions`, { method: "POST", headers, body: form });
  if (!created.ok) throw new Error(`HTTP ${created.status}: ${await created.text()}`);
  let job = (await created.json()) as Job;
  console.log(`job ${job.id}: ${job.status}`);

  while (job.status === "queued" || job.status === "in_progress") {
    await new Promise((resolve) => setTimeout(resolve, 5_000));
    job = (await (await fetch(`${BASE_URL}/v1/audio/transcriptions/${job.id}`, { headers })).json()) as Job;
  }

  if (job.status === "completed" && job.result) console.log(job.result.text);
  else throw new Error(`${job.status}: ${job.error?.message}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

// Live streaming transcription requires the transcribe feature and is not allowed by default.
// npm install ws   (Node 18+, saved as stream.mjs)
import fs from "node:fs";
import WebSocket from "ws";

// Add &disable_endpointing=true to keep a segment open through pauses (e.g. Qur'an recitation).
const URL = "wss://api.fanar.qa/v1/audio/transcriptions/stream?model=Fanar-3.0-Aura-Transcribe";
const ws = new WebSocket(URL, { headers: { Authorization: "Bearer YOUR_API_KEY" } });

// The upgrade was refused (401, 403, 422, 429, 503) -- nothing was streamed.
ws.on("unexpected-response", (req, res) => {
  console.error(`refused: HTTP ${res.statusCode}`, res.headers["retry-after"] ?? "");
});

ws.on("message", (data) => {
  const event = JSON.parse(data.toString());
  switch (event.type) {
    case "session.started":
      console.log(`session ${event.id}: up to ${event.max_duration_seconds}s`);
      streamFile("sample.wav");
      break;
    case "transcript.partial": // the open segment so far; replace it in place
      process.stdout.write(`\r... ${event.text}`);
      break;
    case "transcript.final": // that segment is done; keep it
      process.stdout.write(`\r${event.text}\n`);
      break;
    case "session.expiring":
      console.log(`\n${event.seconds_remaining}s left in this session`);
      break;
    case "error":
      console.error(`\nerror ${event.code}: ${event.message}`);
      break;
    case "session.ended":
      console.log(`\nended (${event.reason}): ${event.text}`);
      break;
  }
});

ws.on("close", (code) => console.log(`closed with ${code}`));

async function streamFile(path) {
  // A canonical 16 kHz mono 16-bit WAV: skip its 44-byte header, send 100 ms (3200 bytes) at a time.
  const pcm = fs.readFileSync(path).subarray(44);
  for (let i = 0; i < pcm.length; i += 3200) {
    if (ws.readyState !== WebSocket.OPEN) return;
    ws.send(pcm.subarray(i, i + 3200));
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
